git log --since="3 months ago" --no-merges --format='C%x09%H%x09AI=%(trailers:key=Co-Authored-By,valueonly,separator=%x20)%x09ENT=%(trailers:key=Entire-Checkpoint,valueonly,separator=%x20)' | perl -ne '
chomp; my ($c,$h,$ai,$ent) = split /\t/;
$total++;
my $isai = ($ai =~ /claude|droid|copilot|cursor|gemini|codex|opencode/i) ? 1 : 0;
my $isent = ($ent =~ /ENT=.+/) ? 1 : 0;
$aiTot+=$isai; $entTot+=$isent; $both++ if $isai && $isent; $aiOnly++ if $isai && !$isent; $entOnly++ if !$isai && $isent;
END { print "total=$total ai=$aiTot entire=$entTot both=$both ai_no_entire=$aiOnly entire_no_ai=$entOnly\n" }'

git log --since="3 months ago" --no-merges --format='%H%x09%an%x09AI=%(trailers:key=Co-Authored-By,valueonly,separator=%x20)%x09ENT=%(trailers:key=Entire-Checkpoint,valueonly,separator=%x20)' | perl -ane '
chomp; my ($h,$an,$ai,$ent) = split /\t/;
next unless $ai =~ /claude|droid|copilot|cursor|gemini|codex|opencode/i;
next if $ent =~ /ENT=.+/;
my ($agent) = $ai =~ /(claude|droid|copilot|cursor|gemini|codex|opencode)/i;
print lc($agent), "\t", $an, "\n";' | sort | uniq -c | sort -rn | head -15

git log --since="3 months ago" --no-merges --format='%H%x09%cn <%ce>%x09AI=%(trailers:key=Co-Authored-By,valueonly,separator=%x20)%x09ENT=%(trailers:key=Entire-Checkpoint,valueonly,separator=%x20)' | perl -ane '
chomp; my ($h,$committer,$ai,$ent) = split /\t/;
next unless $ai =~ /claude|droid|copilot|cursor|gemini|codex|opencode/i;
next if $ent =~ /ENT=.+/;
print $committer, "\n";' | sort | uniq -c | sort -rn | head -10

